import 'dart:convert';

import 'package:http/http.dart' as http;

Future<Map<String, dynamic>> fetchRepo(String name) async {
  final uri = Uri.parse('https://api.github.com/repos/flutter/$name');
  final response = await http.get(uri, headers: {'Accept': 'application/vnd.github+json'});

  if (response.statusCode != 200) {
    throw Exception('GitHub answered ${response.statusCode}');
  }
  return jsonDecode(response.body) as Map<String, dynamic>;
}

import 'package:flutter/material.dart';

class RepoStars extends StatelessWidget {
  const RepoStars({super.key});

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<Map<String, dynamic>>(
      future: fetchRepo('flutter'),
      builder: (context, snapshot) {
        if (snapshot.connectionState != ConnectionState.done) {
          return const Center(child: CircularProgressIndicator());
        }
        if (snapshot.hasError) {
          return Text('Failed: ${snapshot.error}');
        }
        return Text('Stars: ${snapshot.data!['stargazers_count']}');
      },
    );
  }
}

import 'dart:convert';

import 'package:http/http.dart' as http;

Future<void> createIssue(String title) async {
  final response = await http.post(
    Uri.parse('https://api.github.com/repos/flutter/flutter/issues'),
    headers: {
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json',
    },
    body: jsonEncode({'title': title}),
  );

  if (response.statusCode != 201) {
    throw Exception('Create failed: ${response.statusCode} ${response.body}');
  }
}

